// Pre-process email — kiểm tra trạng thái đọc và chuẩn bị dữ liệu cho LLM Chain
const email = $input.first().json;

// Bỏ qua email đã đọc
if (email.isRead === true) {
  console.log('[SKIP] Email đã đọc: id=' + email.id + ' subject="' + email.subject + '"');
  return [];
}

const subject = email.subject || '(Không có tiêu đề)';
const fromAddress = email.from?.emailAddress?.address || '';
const fromName = email.from?.emailAddress?.name || 'Không rõ';
const bodyPreview = (email.bodyPreview || '').substring(0, 500);
const importance = email.importance || 'normal';

// Pass through email data — prompt sẽ được build trong Chain node
return [{
  json: {
    id: email.id,
    subject: subject,
    from: email.from,
    from_name: fromName,
    from_address: fromAddress,
    bodyPreview: bodyPreview,
    receivedDateTime: email.receivedDateTime,
    importance: importance
  }
}];

// Parse JSON response từ Gemini LLM Chain
// LLM Chain output: $json.text (string)
const emailData = $('Pre-process Email').first().json;
const rawText = $input.first().json.text || '';

// Strip markdown code blocks nếu model bọc trong ```json
let cleanText = rawText.trim();
if (cleanText.startsWith('```json')) {
  cleanText = cleanText.replace(/^```json\n?/, '').replace(/\n?```$/, '');
} else if (cleanText.startsWith('```')) {
  cleanText = cleanText.replace(/^```\n?/, '').replace(/\n?```$/, '');
}

const defaultClassification = {
  category: 'normal',
  action: 'notify_quiet',
  priority: 'medium',
  reason: 'Fallback: AI parse thất bại — dùng mặc định'
};

let classification = Object.assign({}, defaultClassification);

try {
  const parsed = JSON.parse(cleanText);
  classification = Object.assign({}, defaultClassification, parsed);
} catch (e) {
  console.error('[ERROR] Parse Gemini response thất bại: ' + e.message);
  console.error('Raw text (300 chars): ' + rawText.substring(0, 300));
}

// Validate và normalize — tránh giá trị không hợp lệ làm hỏng Switch node
if (!['important','newsletter_promo','normal'].includes(classification.category)) classification.category = 'normal';
if (!['notify_interactive','auto_archive','notify_quiet'].includes(classification.action)) classification.action = 'notify_quiet';
if (!['high','medium','low'].includes(classification.priority)) classification.priority = 'medium';

console.log('[Gemini] ' + classification.category + ' | ' + classification.action + ' | ' + classification.reason);

return [{
  json: {
    id: emailData.id,
    subject: emailData.subject,
    from: emailData.from,
    bodyPreview: emailData.bodyPreview,
    receivedDateTime: emailData.receivedDateTime,
    importance: emailData.importance,
    category: classification.category,
    action: classification.action,
    priority: classification.priority,
    ai_reason: classification.reason || '',
    classified_by: 'gemini-2.0-flash',
    classified_at: new Date().toISOString()
  }
}];

// Build Slack Block Kit payload để gửi interactive message
const d = $input.first().json;
const slackChannelId = $('Config Vars').first().json.slackChannelId;

const fromName = d.from?.emailAddress?.name || 'Không rõ';
const fromAddr = d.from?.emailAddress?.address || '';
const subject  = d.subject || '(Không có tiêu đề)';
const preview  = d.bodyPreview || 'Không có nội dung xem trước.';
const aiReason = d.ai_reason || 'N/A';
const priority = d.priority || 'medium';
const emailId  = d.id || '';
const receivedAt = d.receivedDateTime
  ? new Date(d.receivedDateTime).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })
  : 'Không rõ';

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: '📧 Outlook Inbox Manager', emoji: true }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Email quan trọng mới!* 🔴

*Người gửi:* ${fromName} <${fromAddr}>
*Chủ đề:* ${subject}
*Thời gian:* ${receivedAt}

*Xem trước:*
> ${preview.substring(0, 200)}`
    }
  },
  {
    type: 'context',
    elements: [{
      type: 'mrkdwn',
      text: `🤖 *Gemini AI:* ${aiReason} | _Priority: ${priority}_`
    }]
  },
  {
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Lưu trữ 📦', emoji: true },
        style: 'primary',
        value: emailId,
        action_id: 'archive'
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Đánh dấu đã đọc ✅', emoji: true },
        value: emailId,
        action_id: 'mark_read'
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Gắn cờ ⭐️', emoji: true },
        value: emailId,
        action_id: 'flag'
      }
    ]
  }
];

return [{
  json: {
    channel: slackChannelId,
    text: `📧 Email quan trọng từ ${fromName}: ${subject}`,
    blocks: blocks,
    // Pass through email data để các node sau dùng
    _emailId: emailId,
    _subject: subject
  }
}];

const body = $input.first().json.body;
if (!body) throw new Error('Không tìm thấy body từ Slack webhook.');
if (!body.payload) throw new Error('Không tìm thấy payload. Slack phải gửi application/x-www-form-urlencoded.');

let payload;
try { payload = JSON.parse(body.payload); } catch (e) { throw new Error('Không parse được payload JSON: ' + e.message); }
if (!payload.actions?.length) throw new Error('Payload không chứa actions.');

const action = payload.actions[0];
return [{ json: {
  action_id: action.action_id,
  email_id: action.value,
  response_url: payload.response_url,
  user_name: payload.user?.username || payload.user?.name || 'unknown',
  channel_id: payload.channel?.id,
  message_ts: payload.message?.ts,
  original_blocks: payload.message?.blocks || []
}}];

const slackData = $('Parse Slack Payload').first().json;
const updatedBlocks = (slackData.original_blocks || []).filter(b => b.type !== 'actions');
const actionMap = { archive: '📦 Đã lưu trữ', mark_read: '✅ Đã đánh dấu đã đọc', flag: '⭐️ Đã gắn nhãn quan trọng' };
const actionText = actionMap[slackData.action_id] || '❓ Hành động: ' + slackData.action_id;
const processedAt = new Date().toLocaleTimeString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour: '2-digit', minute: '2-digit', second: '2-digit' });
updatedBlocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: '🟢 *Trạng thái:* ' + actionText + ' | Người xử lý: *@' + slackData.user_name + '* lúc ' + processedAt }] });
return [{ json: { response_url: slackData.response_url, payload: { blocks: updatedBlocks, replace_original: true } } }];
